21	func TestIsOutdated(t *testing.T) {
22		tests := []struct {
23			current string
24			latest  string
25			want    bool
26			desc    string
27		}{
28			// Standard semver cases
29			{"1.0.0", "1.0.1", true, "patch version bump"},
30			{"1.0.0", "1.1.0", true, "minor version bump"},
31			{"1.0.0", "2.0.0", true, "major version bump"},
32			{"1.0.1", "1.0.0", false, "current is newer"},
33			{"2.0.0", "1.9.9", false, "current major is higher"},
34			{"1.0.0", "1.0.0", false, "same version"},
35	
36			// v-prefix handling
37			{"v1.0.0", "v1.0.1", true, "with v prefix"},
38			{"v1.0.0", "1.0.1", true, "mixed v prefix"},
39			{"1.0.0", "v1.0.1", true, "mixed v prefix reversed"},
40	
41			// Pre-release versions (semver uses hyphen)
42			{"1.0.0-rc1", "1.0.0", true, "prerelease in current"},
43			{"1.0.0", "1.0.1-rc1", true, "prerelease in latest is still newer"},
44			{"0.6.3-nightly.202605250745.b5855692.0.20260527023747-77e1fedc5741", "0.6.4", false, "pseudo-version (local dev build) skips check"},
45	
46			// Nightly-vs-nightly comparisons (same channel)
47			{"0.5.3-nightly.202604051159.abc1234", "0.5.3-nightly.202604061200.def5678", true, "older nightly is outdated by newer nightly"},
48			{"0.5.3-nightly.202604061200.def5678", "0.5.3-nightly.202604051159.abc1234", false, "newer nightly is not outdated by older nightly"},
49			{"0.5.3-nightly.202604061200.abc1234", "0.5.3-nightly.202604061200.abc1234", false, "same nightly is not outdated"},
50		}
51	
52		for _, tt := range tests {
53			t.Run(tt.desc, func(t *testing.T) {
54				got := isOutdated(tt.current, tt.latest)
55				if got != tt.want {
56					t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
57				}
58			})
59		}
60	}
